{
  "variables": {
    "CORTE": [1, 2, 3, 4],
    "SOLDADURA": [1, 2, 3, 4],
    "PINTURA": [1, 2, 3, 4],
    "INSPECCION": [1, 2, 3, 4]
  },
  "constraints": [
    {"id": "R1", "expr": "CORTE != SOLDADURA"},
    {"id": "R2", "expr": "SOLDADURA != PINTURA"},
    {"id": "R3", "expr": "PINTURA != INSPECCION"},
    {"id": "R4", "expr": "CORTE < SOLDADURA"},
    {"id": "R5", "expr": "SOLDADURA < PINTURA"},
    {"id": "R6", "expr": "INSPECCION > SOLDADURA"},
    {"id": "R7", "expr": "not (PINTURA == INSPECCION + 1)"}
  ]
}
